from modules.analysis import analyze_household
from modules.energy_models import HouseholdProfile, ApplianceUsage
import json
def run(input_json: str) -> str:
    data = json.loads(input_json)
    profile = HouseholdProfile(name=data.get('name','Home'), city=data.get('city',''), occupants=data.get('occupants',3))
    for a in data.get('appliances',[]):
        profile.add_appliance(ApplianceUsage(**a))
    report = analyze_household(profile)
    return json.dumps(report, indent=2)

